META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–4: ಅರ್ಜುನ ವಿಶ್ವರೂಪವನ್ನು ನೋಡಲು ಬಯಸುತ್ತಾನೆ; 5–8: ಶ್ರೀಕೃಷ್ಣ ಅವನಿಗೆ ದಿವ್ಯ ದೃಷ್ಟಿ ಕೊಡುತ್ತಾನೆ; 9–14: ಸಂಜಯ ಆ ರೂಪವನ್ನು ವರ್ಣಿಸುತ್ತಾನೆ, ಸಾವಿರ ಸೂರ್ಯರ ಬೆಳಕು; 15–31: ಅರ್ಜುನ ಆ ರೂಪದಲ್ಲಿ ದೇವತೆಗಳು, ಲೋಕಗಳು ಮತ್ತು ಯೋಧರನ್ನು ಕಂಡು ಭಯಪಡುತ್ತಾನೆ; 32–34: "ನಾನು ಕಾಲ"; 35–46: ಅರ್ಜುನ ನಮಸ್ಕರಿಸಿ, ಕ್ಷಮೆ ಕೇಳಿ, ಸೌಮ್ಯ ರೂಪವನ್ನು ತೋರಿಸಲು ಪ್ರಾರ್ಥಿಸುತ್ತಾನೆ; 47–55: ಶ್ರೀಕೃಷ್ಣ ಮತ್ತೆ ಸೌಮ್ಯನಾಗುತ್ತಾನೆ, ಅನನ್ಯ ಭಕ್ತಿಯಿಂದಲೇ ಅವನು ಕಾಣುತ್ತಾನೆ.',
)
T = {
1: 'ಅರ್ಜುನ ಹೇಳಿದನು: ನನ್ನ ಮೇಲಿನ ಕರುಣೆಯಿಂದ ನೀವು ಆತ್ಮದ ಬಗ್ಗೆ ಪರಮ ರಹಸ್ಯವನ್ನು ಹೇಳಿದಿರಿ. ನಿಮ್ಮ ಮಾತುಗಳಿಂದ ನನ್ನ ಈ ಮೋಹ ದೂರವಾಗಿದೆ.',
2: 'ಹೇ ಕಮಲನಯನ, ಜೀವಿಗಳ ಹುಟ್ಟು ಮತ್ತು ಲಯದ ಬಗ್ಗೆ, ನಿಮ್ಮ ಅವಿನಾಶಿ ಮಹಿಮೆಯ ಬಗ್ಗೆಯೂ ನಿಮ್ಮಿಂದ ವಿಸ್ತಾರವಾಗಿ ಕೇಳಿದ್ದೇನೆ.',
3: 'ಹೇ ಪರಮೇಶ್ವರ, ನಿಮ್ಮನ್ನು ನೀವು ವರ್ಣಿಸಿದಂತೆಯೇ ನೀವಿದ್ದೀರಿ. ಹೇ ಪುರುಷೋತ್ತಮ, ನಿಮ್ಮ ಈಶ್ವರ ರೂಪವನ್ನು ನೋಡಲು ನನಗೆ ಆಸೆಯಾಗಿದೆ.',
4: 'ಹೇ ಪ್ರಭು, ನಾನು ಅದನ್ನು ನೋಡಬಲ್ಲೆ ಎಂದು ನೀವು ಭಾವಿಸಿದರೆ, ಹೇ ಯೋಗೇಶ್ವರ, ನಿಮ್ಮ ಅವಿನಾಶಿ ಸ್ವರೂಪವನ್ನು ನನಗೆ ತೋರಿಸಿ.',
5: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಪಾರ್ಥ, ನೂರಾರು, ಸಾವಿರಾರು ನನ್ನ ರೂಪಗಳನ್ನು ನೋಡು: ದಿವ್ಯವಾದ, ಬಗೆಬಗೆಯ, ಅನೇಕ ಬಣ್ಣ ಮತ್ತು ಆಕಾರಗಳ ರೂಪಗಳು.',
6: 'ಹೇ ಭಾರತ, ಆದಿತ್ಯರನ್ನು, ವಸುಗಳನ್ನು, ರುದ್ರರನ್ನು, ಅಶ್ವಿನೀಕುಮಾರರನ್ನು ಮತ್ತು ಮರುತ್ತರನ್ನು ನೋಡು. ಹಿಂದೆಂದೂ ನೋಡದ ಅನೇಕ ಅದ್ಭುತಗಳನ್ನು ನೋಡು.',
7: 'ಹೇ ಗುಡಾಕೇಶ, ಚರಾಚರಗಳೊಂದಿಗೆ ಇಡೀ ಜಗತ್ತನ್ನು, ನೀನು ನೋಡಲು ಬಯಸುವ ಬೇರೆ ಏನನ್ನಾದರೂ, ಇಲ್ಲಿ ನನ್ನ ದೇಹದಲ್ಲಿ ಒಂದೇ ಕಡೆ ಈಗ ನೋಡು.',
8: 'ಆದರೆ ನಿನ್ನ ಈ ಕಣ್ಣುಗಳಿಂದ ನೀನು ನನ್ನನ್ನು ನೋಡಲಾರೆ. ನಿನಗೆ ದಿವ್ಯ ದೃಷ್ಟಿ ಕೊಡುತ್ತೇನೆ; ನನ್ನ ಈಶ್ವರ ಯೋಗಶಕ್ತಿಯನ್ನು ನೋಡು.',
9: 'ಸಂಜಯ ಹೇಳಿದನು: ಹೇ ರಾಜನೇ, ಹೀಗೆ ಹೇಳಿ ಮಹಾಯೋಗೇಶ್ವರನಾದ ಹರಿ ಅರ್ಜುನನಿಗೆ ತನ್ನ ಪರಮ ಈಶ್ವರ ರೂಪವನ್ನು ತೋರಿಸಿದನು.',
10: 'ಅನೇಕ ಮುಖಗಳು ಮತ್ತು ಕಣ್ಣುಗಳು, ಅನೇಕ ಅದ್ಭುತ ದೃಶ್ಯಗಳು, ಅನೇಕ ದಿವ್ಯ ಆಭರಣಗಳು, ಎತ್ತಿಹಿಡಿದ ಅನೇಕ ದಿವ್ಯ ಆಯುಧಗಳುಳ್ಳ ರೂಪ ಅದು.',
11: 'ದಿವ್ಯ ಮಾಲೆಗಳು ಮತ್ತು ವಸ್ತ್ರಗಳನ್ನು ಧರಿಸಿದ, ದಿವ್ಯ ಸುಗಂಧ ಲೇಪಿಸಿಕೊಂಡ, ಸರ್ವಾಶ್ಚರ್ಯಮಯ, ಹೊಳೆಯುವ, ಅನಂತ, ಎಲ್ಲ ದಿಕ್ಕುಗಳಿಗೂ ಮುಖವಿರುವ ದೇವ.',
13: 'ಆಗ ಪಾಂಡವ ದೇವದೇವನ ದೇಹದಲ್ಲಿ ಅನೇಕ ರೀತಿಯಲ್ಲಿ ವಿಭಾಗವಾದ ಇಡೀ ಜಗತ್ತನ್ನು ಒಂದೇ ಕಡೆ ನೋಡಿದನು.',
14: 'ಆಗ ಆಶ್ಚರ್ಯದಿಂದ ತುಂಬಿ, ರೋಮಾಂಚನಗೊಂಡು, ಧನಂಜಯ ತಲೆಬಾಗಿ ದೇವನಿಗೆ ನಮಸ್ಕರಿಸಿ, ಕೈಮುಗಿದು ಹೇಳಿದನು.',
15: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ದೇವ, ನಿಮ್ಮ ದೇಹದಲ್ಲಿ ಎಲ್ಲ ದೇವತೆಗಳನ್ನೂ, ಬಗೆಬಗೆಯ ಜೀವಿಗಳ ಸಮೂಹಗಳನ್ನೂ ನೋಡುತ್ತಿದ್ದೇನೆ: ಕಮಲಾಸನದಲ್ಲಿ ಕುಳಿತ ಬ್ರಹ್ಮ, ಎಲ್ಲ ಋಷಿಗಳು ಮತ್ತು ದಿವ್ಯ ಸರ್ಪಗಳು.',
16: 'ಅನೇಕ ಕೈಗಳು, ಹೊಟ್ಟೆಗಳು, ಮುಖಗಳು ಮತ್ತು ಕಣ್ಣುಗಳುಳ್ಳ ನಿಮ್ಮನ್ನು ಎಲ್ಲ ಕಡೆ ಅನಂತ ರೂಪದಲ್ಲಿ ನೋಡುತ್ತಿದ್ದೇನೆ. ಹೇ ವಿಶ್ವೇಶ್ವರ, ವಿಶ್ವರೂಪ, ನಿಮ್ಮ ಅಂತ್ಯ, ಮಧ್ಯ, ಆದಿ ಯಾವುದೂ ಕಾಣುತ್ತಿಲ್ಲ.',
17: 'ಕಿರೀಟ, ಗದೆ ಮತ್ತು ಚಕ್ರ ಧರಿಸಿದ, ಎಲ್ಲ ಕಡೆ ಹೊಳೆಯುವ ತೇಜೋರಾಶಿಯಾದ ನಿಮ್ಮನ್ನು ನೋಡುತ್ತಿದ್ದೇನೆ. ಉರಿಯುವ ಬೆಂಕಿ ಮತ್ತು ಸೂರ್ಯನಂತಹ ಕಾಂತಿಯಿಂದ, ಅಳೆಯಲಾಗದ ನಿಮ್ಮನ್ನು ನೋಡುವುದು ಕಷ್ಟ.',
18: 'ನೀವು ತಿಳಿಯಬೇಕಾದ ಪರಮ ಅಕ್ಷರ, ಈ ವಿಶ್ವದ ಪರಮ ಆಶ್ರಯ. ನೀವು ಅವಿನಾಶಿ, ಶಾಶ್ವತ ಧರ್ಮದ ರಕ್ಷಕ; ನೀವೇ ಸನಾತನ ಪುರುಷ ಎಂದು ನನ್ನ ಅಭಿಪ್ರಾಯ.',
19: 'ಆದಿ, ಮಧ್ಯ, ಅಂತ್ಯವಿಲ್ಲದ, ಅನಂತ ಶಕ್ತಿ ಮತ್ತು ಅಸಂಖ್ಯ ಬಾಹುಗಳುಳ್ಳ, ಚಂದ್ರಸೂರ್ಯರೇ ಕಣ್ಣುಗಳಾಗಿರುವ, ಉರಿಯುವ ಬೆಂಕಿಯೇ ಮುಖವಾಗಿರುವ, ನಿಮ್ಮ ತೇಜಸ್ಸಿನಿಂದ ಈ ವಿಶ್ವವನ್ನು ತಪಿಸುತ್ತಿರುವ ನಿಮ್ಮನ್ನು ನೋಡುತ್ತಿದ್ದೇನೆ.',
20: 'ಭೂಮ್ಯಾಕಾಶಗಳ ನಡುವಿನ ಈ ಸ್ಥಳ ಮತ್ತು ಎಲ್ಲ ದಿಕ್ಕುಗಳು ನಿಮ್ಮೊಬ್ಬರಿಂದಲೇ ತುಂಬಿವೆ. ಹೇ ಮಹಾತ್ಮ, ನಿಮ್ಮ ಈ ಅದ್ಭುತ ಮತ್ತು ಭಯಂಕರ ರೂಪವನ್ನು ನೋಡಿ ಮೂರು ಲೋಕಗಳೂ ನಡುಗುತ್ತಿವೆ.',
21: 'ಈ ದೇವತೆಗಳ ಸಮೂಹಗಳು ನಿಮ್ಮಲ್ಲಿ ಪ್ರವೇಶಿಸುತ್ತಿವೆ; ಕೆಲವರು ಭಯದಿಂದ ಕೈಮುಗಿದು ಸ್ತುತಿಸುತ್ತಿದ್ದಾರೆ. ಮಹರ್ಷಿಗಳು ಮತ್ತು ಸಿದ್ಧರ ಸಮೂಹಗಳು "ಸ್ವಸ್ತಿ" ಎನ್ನುತ್ತಾ ಮಹಾ ಸ್ತೋತ್ರಗಳಿಂದ ನಿಮ್ಮನ್ನು ಸ್ತುತಿಸುತ್ತಿದ್ದಾರೆ.',
22: 'ರುದ್ರರು, ಆದಿತ್ಯರು, ವಸುಗಳು, ಸಾಧ್ಯರು, ವಿಶ್ವೇದೇವರು, ಅಶ್ವಿನೀಕುಮಾರರು, ಮರುತ್ತರು, ಪಿತೃಗಳು, ಗಂಧರ್ವರು, ಯಕ್ಷರು, ಅಸುರರು ಮತ್ತು ಸಿದ್ಧರ ಸಮೂಹಗಳು, ಎಲ್ಲರೂ ಆಶ್ಚರ್ಯದಿಂದ ನಿಮ್ಮನ್ನು ನೋಡುತ್ತಿದ್ದಾರೆ.',
23: 'ಹೇ ಮಹಾಬಾಹು, ಅನೇಕ ಮುಖಗಳು ಮತ್ತು ಕಣ್ಣುಗಳು, ಅನೇಕ ಕೈಗಳು, ತೊಡೆಗಳು ಮತ್ತು ಪಾದಗಳು, ಅನೇಕ ಹೊಟ್ಟೆಗಳು ಮತ್ತು ಭಯಂಕರ ಕೋರೆಹಲ್ಲುಗಳುಳ್ಳ ನಿಮ್ಮ ಮಹಾ ರೂಪವನ್ನು ನೋಡಿ ಲೋಕಗಳು ನಡುಗುತ್ತಿವೆ, ನಾನೂ ಕೂಡ.',
24: 'ಹೇ ವಿಷ್ಣು, ಆಕಾಶವನ್ನು ಮುಟ್ಟುವ, ಅನೇಕ ಬಣ್ಣಗಳಿಂದ ಹೊಳೆಯುವ, ತೆರೆದ ಬಾಯಿಗಳು ಮತ್ತು ಉರಿಯುವ ವಿಶಾಲ ಕಣ್ಣುಗಳುಳ್ಳ ನಿಮ್ಮನ್ನು ನೋಡಿ ನನ್ನ ಮನಸ್ಸು ಭಯದಿಂದ ನಡುಗುತ್ತಿದೆ; ನನಗೆ ಧೈರ್ಯವೂ ಇಲ್ಲ, ಶಾಂತಿಯೂ ಇಲ್ಲ.',
25: 'ಕೋರೆಹಲ್ಲುಗಳಿಂದ ಭಯಂಕರವಾದ, ಪ್ರಳಯಾಗ್ನಿಯಂತೆ ಉರಿಯುವ ನಿಮ್ಮ ಮುಖಗಳನ್ನು ನೋಡಿ ನನಗೆ ದಿಕ್ಕುಗಳು ತಿಳಿಯುತ್ತಿಲ್ಲ, ಸುಖ ಸಿಗುತ್ತಿಲ್ಲ. ಹೇ ದೇವೇಶ, ಜಗನ್ನಿವಾಸ, ಪ್ರಸನ್ನರಾಗಿ.',
26: 'ಧೃತರಾಷ್ಟ್ರನ ಎಲ್ಲ ಮಕ್ಕಳೂ, ರಾಜರ ಸಮೂಹಗಳೊಂದಿಗೆ, ಭೀಷ್ಮ, ದ್ರೋಣ ಮತ್ತು ಆ ಸೂತಪುತ್ರ (ಕರ್ಣ), ನಮ್ಮ ಮುಖ್ಯ ಯೋಧರೊಂದಿಗೆ,',
27: 'ಕೋರೆಹಲ್ಲುಗಳಿಂದ ಭಯಂಕರವಾದ ನಿಮ್ಮ ಬಾಯಿಗಳಲ್ಲಿ ವೇಗವಾಗಿ ಪ್ರವೇಶಿಸುತ್ತಿದ್ದಾರೆ. ಕೆಲವರು ಪುಡಿಯಾದ ತಲೆಗಳೊಂದಿಗೆ ನಿಮ್ಮ ಹಲ್ಲುಗಳ ನಡುವೆ ಸಿಕ್ಕಿಕೊಂಡಿರುವುದು ಕಾಣುತ್ತಿದೆ.',
28: 'ನದಿಗಳ ಅನೇಕ ಜಲಪ್ರವಾಹಗಳು ಸಮುದ್ರದ ಕಡೆಗೇ ಓಡುವಂತೆ, ಈ ನರಲೋಕದ ವೀರರು ಉರಿಯುವ ನಿಮ್ಮ ಬಾಯಿಗಳಲ್ಲಿ ಪ್ರವೇಶಿಸುತ್ತಿದ್ದಾರೆ.',
29: 'ಉರಿಯುವ ಬೆಂಕಿಗೆ ಪತಂಗಗಳು ನಾಶಕ್ಕಾಗಿ ವೇಗವಾಗಿ ಪ್ರವೇಶಿಸುವಂತೆ, ಈ ಲೋಕಗಳೂ ನಾಶಕ್ಕಾಗಿ ನಿಮ್ಮ ಬಾಯಿಗಳಲ್ಲಿ ವೇಗವಾಗಿ ಪ್ರವೇಶಿಸುತ್ತಿವೆ.',
30: 'ಉರಿಯುವ ಬಾಯಿಗಳಿಂದ ಎಲ್ಲ ಲೋಕಗಳನ್ನೂ ಎಲ್ಲ ಕಡೆಯಿಂದ ನುಂಗುತ್ತಾ ನೀವು ನಾಲಿಗೆಯಿಂದ ಚಪ್ಪರಿಸುತ್ತಿದ್ದೀರಿ. ಹೇ ವಿಷ್ಣು, ನಿಮ್ಮ ಭಯಂಕರ ಕಿರಣಗಳು ಇಡೀ ಜಗತ್ತನ್ನು ತೇಜಸ್ಸಿನಿಂದ ತುಂಬಿ ತಪಿಸುತ್ತಿವೆ.',
31: 'ಭಯಂಕರ ರೂಪದ ನೀವು ಯಾರು ಎಂದು ನನಗೆ ಹೇಳಿ. ಹೇ ದೇವಶ್ರೇಷ್ಠ, ನಿಮಗೆ ನಮಸ್ಕಾರ, ಪ್ರಸನ್ನರಾಗಿ. ಆದಿಪುರುಷರಾದ ನಿಮ್ಮನ್ನು ತಿಳಿಯಲು ಬಯಸುತ್ತೇನೆ, ಏಕೆಂದರೆ ನಿಮ್ಮ ಉದ್ದೇಶ ನನಗೆ ಅರ್ಥವಾಗುತ್ತಿಲ್ಲ.',
33: 'ಆದ್ದರಿಂದ ನೀನು ಎದ್ದೇಳು, ಕೀರ್ತಿಯನ್ನು ಪಡೆ. ಶತ್ರುಗಳನ್ನು ಗೆದ್ದು ಸಮೃದ್ಧ ರಾಜ್ಯವನ್ನು ಅನುಭವಿಸು. ಇವರೆಲ್ಲರೂ ಈಗಾಗಲೇ ನನ್ನಿಂದ ಕೊಲ್ಲಲ್ಪಟ್ಟಿದ್ದಾರೆ; ಹೇ ಸವ್ಯಸಾಚಿ, ನೀನು ಕೇವಲ ನಿಮಿತ್ತಮಾತ್ರನಾಗು.',
34: 'ದ್ರೋಣ, ಭೀಷ್ಮ, ಜಯದ್ರಥ, ಕರ್ಣ ಮತ್ತು ಇತರ ವೀರ ಯೋಧರು ಈಗಾಗಲೇ ನನ್ನಿಂದ ಕೊಲ್ಲಲ್ಪಟ್ಟಿದ್ದಾರೆ; ನೀನು ಅವರನ್ನು ಕೊಲ್ಲು. ಕಳವಳಪಡಬೇಡ. ಯುದ್ಧ ಮಾಡು, ಯುದ್ಧದಲ್ಲಿ ಶತ್ರುಗಳನ್ನು ಗೆಲ್ಲುತ್ತೀಯ.',
35: 'ಸಂಜಯ ಹೇಳಿದನು: ಕೇಶವನ ಈ ಮಾತುಗಳನ್ನು ಕೇಳಿ ಕಿರೀಟಧಾರಿ (ಅರ್ಜುನ) ನಡುಗುತ್ತಾ ಕೈಮುಗಿದು ನಮಸ್ಕರಿಸಿದನು. ಬಹಳ ಭಯಪಟ್ಟು, ಮತ್ತೆ ಬಾಗಿ ನಮಸ್ಕರಿಸಿ, ಗದ್ಗದ ಸ್ವರದಲ್ಲಿ ಶ್ರೀಕೃಷ್ಣನಿಗೆ ಹೇಳಿದನು.',
36: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಹೃಷೀಕೇಶ, ನಿಮ್ಮ ಕೀರ್ತನೆಯಿಂದ ಜಗತ್ತು ಆನಂದಿಸಿ ನಿಮ್ಮ ಮೇಲಿನ ಪ್ರೀತಿಯಿಂದ ತುಂಬುವುದು ಸರಿಯೇ. ರಾಕ್ಷಸರು ಭಯದಿಂದ ಎಲ್ಲ ದಿಕ್ಕುಗಳಿಗೂ ಓಡುತ್ತಿದ್ದಾರೆ, ಸಿದ್ಧರ ಎಲ್ಲ ಸಮೂಹಗಳೂ ನಿಮಗೆ ನಮಸ್ಕರಿಸುತ್ತಿವೆ.',
37: 'ಹೇ ಮಹಾತ್ಮ, ಬ್ರಹ್ಮನಿಗೂ ಆದಿಕಾರಣರಾದ, ಅವನಿಗಿಂತಲೂ ಮಹಾನರಾದ ನಿಮಗೆ ಅವರು ಏಕೆ ನಮಸ್ಕರಿಸಬಾರದು? ಹೇ ಅನಂತ, ದೇವೇಶ, ಜಗನ್ನಿವಾಸ, ನೀವು ಅಕ್ಷರ, ಸತ್, ಅಸತ್ ಮತ್ತು ಅವುಗಳಾಚೆ ಇರುವುದೂ ಹೌದು.',
38: 'ನೀವು ಆದಿದೇವ, ಪುರಾತನ ಪುರುಷ, ಈ ವಿಶ್ವದ ಪರಮ ಆಶ್ರಯ. ನೀವು ತಿಳಿಯುವವರು, ತಿಳಿಯಬೇಕಾದವರು ಮತ್ತು ಪರಮ ಧಾಮ. ಹೇ ಅನಂತರೂಪ, ಈ ವಿಶ್ವವೆಲ್ಲ ನಿಮ್ಮಿಂದ ವ್ಯಾಪಿಸಿದೆ.',
39: 'ನೀವು ವಾಯು, ಯಮ, ಅಗ್ನಿ, ವರುಣ, ಚಂದ್ರ, ಪ್ರಜಾಪತಿ ಮತ್ತು ಪ್ರಪಿತಾಮಹ. ನಿಮಗೆ ಸಾವಿರ ಬಾರಿ ನಮಸ್ಕಾರ, ಮತ್ತೆ ಮತ್ತೆ ನಮಸ್ಕಾರ.',
40: 'ನಿಮಗೆ ಮುಂದಿನಿಂದ ನಮಸ್ಕಾರ, ಹಿಂದಿನಿಂದ ನಮಸ್ಕಾರ, ಹೇ ಸರ್ವ, ಎಲ್ಲ ಕಡೆಯಿಂದಲೂ ನಮಸ್ಕಾರ. ನಿಮ್ಮ ಶಕ್ತಿ ಅನಂತ, ಪರಾಕ್ರಮ ಅಳತೆಗೆ ಮೀರಿದ್ದು; ನೀವು ಎಲ್ಲವನ್ನೂ ವ್ಯಾಪಿಸಿದ್ದೀರಿ, ಆದ್ದರಿಂದ ನೀವೇ ಎಲ್ಲವೂ.',
41: 'ನಿಮ್ಮ ಈ ಮಹಿಮೆ ತಿಳಿಯದೆ, ನಿಮ್ಮನ್ನು ಗೆಳೆಯನೆಂದು ಭಾವಿಸಿ, ಅಜಾಗರೂಕತೆಯಿಂದ ಅಥವಾ ಪ್ರೀತಿಯಿಂದ "ಹೇ ಕೃಷ್ಣ, ಹೇ ಯಾದವ, ಹೇ ಸಖ" ಎಂದು ಸಲುಗೆಯಿಂದ ಕರೆದಿದ್ದೇನೆ.',
42: 'ಹೇ ಅಚ್ಯುತ, ಆಟದಲ್ಲಿ, ಮಲಗಿದಾಗ, ಕುಳಿತಾಗ, ಊಟ ಮಾಡುವಾಗ, ಒಂಟಿಯಾಗಿ ಅಥವಾ ಇತರರ ಮುಂದೆ, ತಮಾಷೆಗಾಗಿ ನಿಮ್ಮನ್ನು ಅಗೌರವಿಸಿದ್ದರೆ, ಅಳತೆಗೆ ಮೀರಿದ ನಿಮ್ಮಲ್ಲಿ ಕ್ಷಮೆ ಕೇಳುತ್ತೇನೆ.',
43: 'ನೀವು ಈ ಚರಾಚರ ಲೋಕದ ತಂದೆ, ಪೂಜ್ಯರು, ಗುರುಗಳಿಗೂ ಗುರು. ಹೇ ಅಪ್ರತಿಮ ಪ್ರಭಾವದವರೇ, ಮೂರು ಲೋಕಗಳಲ್ಲಿ ನಿಮಗೆ ಸಮಾನರೇ ಇಲ್ಲ, ನಿಮಗಿಂತ ದೊಡ್ಡವರು ಎಲ್ಲಿ?',
44: 'ಆದ್ದರಿಂದ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡಿ, ಪೂಜ್ಯ ಈಶ್ವರರಾದ ನಿಮ್ಮನ್ನು ಪ್ರಸನ್ನರಾಗಲು ಬೇಡುತ್ತೇನೆ. ಹೇ ದೇವ, ತಂದೆ ಮಗನನ್ನು, ಗೆಳೆಯ ಗೆಳೆಯನನ್ನು, ಪ್ರಿಯ ಪ್ರಿಯತಮೆಯನ್ನು ಸಹಿಸುವಂತೆ ನನ್ನನ್ನು ಸಹಿಸಿ.',
45: 'ಹಿಂದೆಂದೂ ನೋಡದ್ದನ್ನು ನೋಡಿ ಸಂತೋಷವಾಗಿದೆ, ಆದರೆ ನನ್ನ ಮನಸ್ಸು ಭಯದಿಂದ ನಡುಗುತ್ತಿದೆ. ಹೇ ದೇವ, ನಿಮ್ಮ ಆ (ಸೌಮ್ಯ) ರೂಪವನ್ನೇ ತೋರಿಸಿ. ಹೇ ದೇವೇಶ, ಜಗನ್ನಿವಾಸ, ಪ್ರಸನ್ನರಾಗಿ.',
46: 'ಕಿರೀಟ, ಗದೆ ಮತ್ತು ಕೈಯಲ್ಲಿ ಚಕ್ರ ಹಿಡಿದ ನಿಮ್ಮನ್ನು ಹಾಗೆಯೇ ನೋಡಲು ಬಯಸುತ್ತೇನೆ. ಹೇ ಸಹಸ್ರಬಾಹು, ವಿಶ್ವಮೂರ್ತಿ, ಆ ಚತುರ್ಭುಜ ರೂಪವನ್ನೇ ಧರಿಸಿ.',
47: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಅರ್ಜುನ, ನಿನ್ನ ಮೇಲೆ ಪ್ರಸನ್ನನಾಗಿ ನನ್ನ ಯೋಗಶಕ್ತಿಯಿಂದ ಈ ಪರಮ ರೂಪವನ್ನು ನಿನಗೆ ತೋರಿಸಿದೆ: ತೇಜೋಮಯ, ವಿಶ್ವರೂಪ, ಅನಂತ ಮತ್ತು ಆದಿ. ನಿನ್ನ ಹೊರತು ಹಿಂದೆ ಇದನ್ನು ಯಾರೂ ನೋಡಿಲ್ಲ.',
48: 'ಹೇ ಕುರುವೀರ, ವೇದಾಧ್ಯಯನದಿಂದಾಗಲಿ, ಯಜ್ಞಗಳಿಂದಾಗಲಿ, ದಾನಗಳಿಂದಾಗಲಿ, ಕರ್ಮಕಾಂಡಗಳಿಂದಾಗಲಿ, ಕಠಿಣ ತಪಸ್ಸುಗಳಿಂದಾಗಲಿ, ಈ ಮಾನವಲೋಕದಲ್ಲಿ ನಿನ್ನ ಹೊರತು ಬೇರೆ ಯಾರೂ ನನ್ನನ್ನು ಈ ರೂಪದಲ್ಲಿ ನೋಡಲಾರರು.',
49: 'ನನ್ನ ಈ ಭಯಂಕರ ರೂಪವನ್ನು ನೋಡಿ ನೀನು ಭಯಪಡಬೇಡ, ಕಳವಳಪಡಬೇಡ. ಭಯವನ್ನು ಬಿಟ್ಟು, ಪ್ರಸನ್ನ ಮನಸ್ಸಿನಿಂದ ನನ್ನ ಆ ರೂಪವನ್ನೇ ಮತ್ತೆ ನೋಡು.',
50: 'ಸಂಜಯ ಹೇಳಿದನು: ಅರ್ಜುನನಿಗೆ ಹೀಗೆ ಹೇಳಿ ವಾಸುದೇವ ತನ್ನ ಸ್ವಂತ ರೂಪವನ್ನು ಮತ್ತೆ ತೋರಿಸಿದನು. ಆ ಮಹಾತ್ಮ ಮತ್ತೆ ಸೌಮ್ಯ ರೂಪ ಧರಿಸಿ ಭಯಗೊಂಡಿದ್ದ ಅರ್ಜುನನನ್ನು ಸಮಾಧಾನಪಡಿಸಿದನು.',
51: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಜನಾರ್ದನ, ನಿಮ್ಮ ಈ ಸೌಮ್ಯ ಮಾನವ ರೂಪವನ್ನು ನೋಡಿ ಈಗ ನನ್ನ ಮನಸ್ಸು ಶಾಂತವಾಗಿದೆ, ನಾನು ಮತ್ತೆ ನನ್ನ ಸ್ವಭಾವಕ್ಕೆ ಮರಳಿದ್ದೇನೆ.',
52: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ನೀನು ನೋಡಿದ ನನ್ನ ಈ ರೂಪವನ್ನು ನೋಡುವುದು ಬಹಳ ಕಷ್ಟ. ದೇವತೆಗಳೂ ಈ ರೂಪವನ್ನು ನೋಡಲು ಸದಾ ಹಂಬಲಿಸುತ್ತಾರೆ.',
53: 'ನೀನು ನನ್ನನ್ನು ನೋಡಿದ ರೀತಿಯಲ್ಲಿ, ವೇದಗಳಿಂದಾಗಲಿ, ತಪಸ್ಸಿನಿಂದಾಗಲಿ, ದಾನದಿಂದಾಗಲಿ, ಯಜ್ಞದಿಂದಾಗಲಿ ನನ್ನನ್ನು ನೋಡಲು ಸಾಧ್ಯವಿಲ್ಲ.',
54: 'ಆದರೆ ಹೇ ಅರ್ಜುನ, ಹೇ ಪರಂತಪ, ಅನನ್ಯ ಭಕ್ತಿಯಿಂದ ಮಾತ್ರ ನನ್ನನ್ನು ಹೀಗೆ ತಿಳಿಯಬಹುದು, ತತ್ತ್ವವಾಗಿ ನೋಡಬಹುದು ಮತ್ತು ನನ್ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು.',
55: 'ಹೇ ಪಾಂಡವ, ನನಗಾಗಿಯೇ ಕರ್ಮ ಮಾಡುವವನು, ನನ್ನನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಭಾವಿಸುವವನು, ನನ್ನ ಭಕ್ತ, ಆಸಕ್ತಿಯಿಲ್ಲದವನು, ಯಾವ ಜೀವಿಯ ಮೇಲೂ ಶತ್ರುತ್ವವಿಲ್ಲದವನು ನನ್ನನ್ನು ಸೇರುತ್ತಾನೆ.',
}
